"""Synthetic source-generated bytes only; no capture logs or real images stored."""
import base64
import hashlib
import importlib.util
from pathlib import Path
import random
import struct
import subprocess
import sys
import tempfile
import unittest
import zlib

TOOL=Path(__file__).resolve().parents[1]/'tools/a04-fb-decode.py'
spec=importlib.util.spec_from_file_location('fb_recovery',TOOL)
decoder=importlib.util.module_from_spec(spec);spec.loader.exec_module(decoder)
ID='0123456789abcdef0123456789abcdef'
OTHER='fedcba9876543210fedcba9876543210'
PREFIX=f'!A04FB1 {ID} '.encode()

def frame(seed=0xa04):
    return decoder.HEADER+random.Random(seed).randbytes(200*320*3)

def records(ppm):
    out=[PREFIX+f'BEGIN 200 320 P6 {len(ppm)}\n'.encode()]
    for offset in range(0,len(ppm),384):
        block=ppm[offset:offset+384]
        out.append(PREFIX+f'DATA {offset} {len(block)} {zlib.crc32(block)&0xffffffff:08x} '.encode()+base64.b64encode(block)+b'\n')
    return out+[PREFIX+f'END {len(ppm)} {hashlib.sha256(ppm).hexdigest()}\n'.encode()]

def split_record(record,at,noise=b'kernel: inserted log\r\nsecond kernel line\n'):
    header,payload=record.rstrip(b'\n').rsplit(b' ',1)
    return header+b' '+payload[:at]+noise+payload[at:]+b'\r\r\n'

def split_twice(record,first,second):
    header,payload=record.rstrip(b'\n').rsplit(b' ',1)
    return (header+b' '+payload[:first]+b'Allowing spawn: kernel\r\nextra log block\n'+
            payload[first:second]+b'Failed open swap: kernel\r\nAKS: another line\n'+
            payload[second:]+b'\r\r\n')

def crc_collision(block):
    """Solve the real CRC32 linear system for a different equal-length block."""
    changed=bytearray(block);changed[0]^=0x80;changed[-4:]=b'\0'*4
    base=zlib.crc32(changed)&0xffffffff;basis={}
    for bit in range(32):
        trial=changed.copy();trial[-4+bit//8]^=1<<(bit%8)
        value=(zlib.crc32(trial)&0xffffffff)^base;mask=1<<bit
        while value:
            pivot=value.bit_length()-1
            if pivot not in basis:basis[pivot]=(value,mask);break
            other,other_mask=basis[pivot];value^=other;mask^=other_mask
    value=(zlib.crc32(block)&0xffffffff)^base;solution=0
    while value:
        pivot=value.bit_length()-1;other,mask=basis[pivot]
        value^=other;solution^=mask
    for bit in range(32):
        if solution>>bit&1:changed[-4+bit//8]^=1<<(bit%8)
    result=bytes(changed)
    assert result!=block and zlib.crc32(result)==zlib.crc32(block)
    return result

class InterleavedDecode(unittest.TestCase):
    def decode(self,wire,step=65536):
        return decoder.decode_chunks((wire[n:n+step] for n in range(0,len(wire),step)),ID,recover_interleaved=True)

    def test_random_pixels_exact_recovery_strict_default_and_stream_boundaries(self):
        for seed in (7,911):
            ppm=frame(seed);lines=records(ppm)
            for index,cut in enumerate((0,1,3,134,511),1):lines[index]=split_record(lines[index],cut)
            lines[-2]=split_record(lines[-2],7)
            wire=b'noise\n'+b''.join(lines)
            with self.assertRaises(decoder.CaptureError):decoder.decode_chunks([wire],ID)
            for step in (1,19,65536):self.assertEqual(self.decode(wire,step),ppm)
            png=decoder.png_from_ppm(self.decode(wire));at=8;compressed=b''
            while at<len(png):
                size=struct.unpack('>I',png[at:at+4])[0];kind=png[at+4:at+8]
                if kind==b'IDAT':compressed+=png[at+8:at+8+size]
                at+=12+size
            raw=zlib.decompress(compressed)
            self.assertEqual(b''.join(raw[y*601+1:(y+1)*601] for y in range(320)),ppm[len(decoder.HEADER):])

    def test_real_crc_and_whole_original_sha_rejections(self):
        ppm=frame();good=records(ppm)
        for failure in ('crc','sha','noncanonical','complete-bad-crc'):
            lines=good.copy();lines[2]=split_record(lines[2],113)
            if failure=='crc':
                fields=good[2].split();fields[-2]=f'{int(fields[-2],16)^1:08x}'.encode()
                lines[2]=split_record(b' '.join(fields)+b'\n',113)
            elif failure=='sha':lines[-1]=PREFIX+f'END {len(ppm)} '.encode()+b'0'*64+b'\n'
            elif failure=='noncanonical':lines[2]=lines[2].replace(b'\r\r\n',b'=\r\r\n')
            else:
                fields=good[3].split();fields[-2]=f'{int(fields[-2],16)^1:08x}'.encode();lines[3]=b' '.join(fields)+b'\n'
            with self.subTest(failure=failure),self.assertRaises(decoder.CaptureError):self.decode(b''.join(lines))

    def test_two_insertions_random_exact_bytes_and_stream_boundaries(self):
        for seed in (104064,123):
            ppm=frame(seed);lines=records(ppm)
            for index,cuts in enumerate(((0,1),(1,3),(37,133),(133,134),(255,511)),1):
                lines[index]=split_twice(lines[index],*cuts)
            lines[-2]=split_twice(lines[-2],1,19)
            wire=b''.join(lines)
            with self.assertRaises(decoder.CaptureError):decoder.decode_chunks([wire],ID)
            for step in (1,23,65536):self.assertEqual(self.decode(wire,step),ppm)

    def test_two_insertions_corruption_sha_and_four_fragments_fail_closed(self):
        ppm=frame(104064);good=records(ppm)
        for failure in ('middle-corrupt','crc','sha','four-fragments','truncated-middle'):
            lines=good.copy();lines[2]=split_twice(lines[2],37,133)
            header,payload=good[2].rstrip(b'\n').rsplit(b' ',1)
            if failure=='middle-corrupt':
                changed=(b'A' if payload[37:38]!=b'A' else b'B')+payload[38:133]
                lines[2]=lines[2].replace(payload[37:133],changed)
            elif failure=='crc':
                fields=good[2].split();fields[-2]=f'{int(fields[-2],16)^1:08x}'.encode()
                lines[2]=split_twice(b' '.join(fields)+b'\n',37,133)
            elif failure=='sha':lines[-1]=PREFIX+f'END {len(ppm)} '.encode()+b'0'*64+b'\n'
            elif failure=='four-fragments':
                lines[2]=(header+b' '+payload[:37]+b'kernel: one\n'+payload[37:83]+
                          b'kernel: two\n'+payload[83:133]+b'kernel: three\n'+payload[133:]+b'\n')
            else:lines[2]=lines[2].replace(payload[37:133],payload[37:132])
            with self.subTest(failure=failure),self.assertRaises(decoder.CaptureError):self.decode(b''.join(lines))

    def test_candidate_attempt_budget_even_after_a_valid_candidate(self):
        ppm=frame();lines=records(ppm)
        # A real valid candidate occurs first. Later pairs remain within byte/
        # line bounds but require more than the fixed candidate search budget.
        lines[2]=split_record(lines[2],133,b'kernel: log\n')
        lines[2]+=(b'A'*510+b':kernel\n')*10+b'A\n'*18
        self.assertLess(len(lines[2]),decoder.MAX_INTERLEAVED_BYTES)
        self.assertLessEqual(len(lines[2].splitlines()),decoder.MAX_INTERLEAVED_LINES)
        with self.assertRaisesRegex(decoder.CaptureError,'candidate attempt limit'):self.decode(b''.join(lines))

    def test_three_fragment_crc_collision_is_still_ambiguous(self):
        ppm=frame();lines=records(ppm)
        header,payload=lines[2].rstrip(b'\n').rsplit(b' ',1)
        collision=base64.b64encode(crc_collision(base64.b64decode(payload)))
        lines[2]=split_twice(lines[2],37,133)+collision+b'\n'
        with self.assertRaisesRegex(decoder.CaptureError,'ambiguous'):self.decode(b''.join(lines))

    def test_distinct_crc_collision_ambiguous_even_when_end_sha_selects_one(self):
        ppm=frame();lines=records(ppm);header,payload=lines[2].rstrip(b'\n').rsplit(b' ',1)
        block=base64.b64decode(payload);other=base64.b64encode(crc_collision(block))
        lines[2]=header+b' kernel: inserted\n'+payload+b'\n'+other+b'\n'
        with self.assertRaisesRegex(decoder.CaptureError,'ambiguous'):self.decode(b''.join(lines))
        # Multiple observations of the same canonical bytes are not distinct candidates.
        lines[2]=header+b' kernel: inserted\n'+payload+b'\n'+payload+b'\n'
        self.assertEqual(self.decode(b''.join(lines)),ppm)

    def test_no_cross_record_borrowing_truncation_or_complex_insertion(self):
        ppm=frame();good=records(ppm);header,payload=good[2].rstrip(b'\n').rsplit(b' ',1)
        cases=[
            good[:2]+[header+b' '+payload[:10]+b'kernel: truncated\n'],
            good[:2]+[header+b' '+payload[:10]+b'kernel: log\n'+payload[10:]+b'\n'],
            good[:2]+[header+b' '+payload[:10]+b'kernel: log\n']+good[3:],
            good[:2]+[header+b' '+payload[:10]+b'kernel: log\n!A04FB1 '+OTHER.encode()+b' BEGIN 200 320 P6 192015\n'+payload[10:]+b'\n']+good[3:],
            good[:2]+[header+b' '+payload[:10]+b'kernel: first\n'+payload[10:40]+b'\n'+payload[40:]+b'\n']+good[3:],
            good[:2]+[header+b' '+payload[:10]+b'kernel: log\nnoise '+PREFIX+b'END 192015 '+b'0'*64+b'\n'+payload[10:]+b'\n']+good[3:],
            good[:2]+[header+b' '+payload[:10]+b'kernel: embedded '+PREFIX+b'DATA broken\n'+payload[10:]+b'\n']+good[3:],
        ]
        for i,lines in enumerate(cases):
            with self.subTest(case=i),self.assertRaises(decoder.CaptureError):self.decode(b''.join(lines))
        # Complete DATA header is mandatory; repair never recreates header fields.
        lines=good.copy();lines[2]=split_record(lines[2],20).replace(b'DATA 384 384',b'DATA broken 384')
        with self.assertRaises(decoder.CaptureError):self.decode(b''.join(lines))

    def test_line_byte_and_recovered_chunk_bounds(self):
        ppm=frame();good=records(ppm)
        noise=[b'kernel: first\n'+b'kernel: extra\n'*decoder.MAX_INTERLEAVED_LINES,
               b'kernel: first\n'+(b'kernel: '+b'x'*990+b'\n')*20,
               b'x'*(decoder.MAX_INTERLEAVED_BYTES+1)+b'\n',
               b'kernel: first\n'+b'x'*(decoder.MAX_INTERLEAVED_BYTES+1)+b'\n']
        for insertion in noise:
            lines=good.copy();lines[2]=split_record(lines[2],10,insertion)
            with self.assertRaises(decoder.CaptureError):self.decode(b''.join(lines))
        lines=good.copy()
        for i in range(1,decoder.MAX_RECOVERED_CHUNKS+2):lines[i]=split_record(lines[i],1)
        with self.assertRaisesRegex(decoder.CaptureError,'recovery limit'):self.decode(b''.join(lines))

    def test_explicit_cli_api_atomic_output_and_sha_failure_no_image(self):
        ppm=frame();lines=records(ppm);lines[2]=split_record(lines[2],3);wire=b''.join(lines)
        with tempfile.TemporaryDirectory() as d:
            p=Path(d);source=p/'wire';source.write_bytes(wire);image=p/'verified.png'
            cmd=[sys.executable,str(TOOL),'--log',str(source),'--frame-id',ID,'--output',str(image)]
            self.assertNotEqual(subprocess.run(cmd,capture_output=True).returncode,0);self.assertFalse(image.exists())
            result=subprocess.run(cmd+['--recover-interleaved'],capture_output=True,text=True)
            self.assertEqual(result.returncode,0,result.stderr)
            self.assertIn(hashlib.sha256(ppm).hexdigest(),result.stdout)
            expected=decoder.png_from_ppm(ppm);self.assertEqual(image.read_bytes(),expected)
            self.assertNotEqual(subprocess.run(cmd+['--recover-interleaved'],capture_output=True).returncode,0)
            self.assertEqual(image.read_bytes(),expected);image.unlink()
            lines[-1]=PREFIX+f'END {len(ppm)} '.encode()+b'0'*64+b'\n';source.write_bytes(b''.join(lines))
            self.assertNotEqual(subprocess.run(cmd+['--recover-interleaved'],capture_output=True).returncode,0)
            self.assertFalse(image.exists())
            self.assertEqual(list(p.glob('*.tmp')),[])

if __name__=='__main__':unittest.main()
